    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        goto cleanup;
    }

    printf("MLX90614 at 0x%02x on %s\n", MLX90614_ADDR, I2C_BUS);

    while (running) {
        int16_t raw;
        if (i2c_read_reg16(fd, 0x06, &raw) == 0) {
            float temp = raw * 0.02 - 273.15;
            printf("Temperature: %.2f C\n", temp);
        } else {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        }
        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4 4
#define GPIO_17 17

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line 4");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request lines as outputs, initial low */
    ret = gpiod_line_request_output(line4, "gpio4", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 4");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line17, "gpio17", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }

    /* Set both high */
    ret = gpiod_line_set_value(line4, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value 4");
        goto cleanup;
    }

    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value 17");
        goto cleanup;
    }

    printf("GPIO 4 and GPIO 17 set HIGH\n");

    /* Wait for signal or exit */
    while (running) {
        sleep(1);
    }

    /* Turn off and release */
    gpiod_line_set_value(line4, 0);
    gpiod_line_set_value(line17, 0);

cleanup:
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

