#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SLEEP_SEC 0.5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int value = 0;
    while (running) {
        if (gpioPWM(PWM_PIN, value) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", PWM_PIN);
            break;
        }
        printf("PWM on GPIO %d = %d\n", PWM_PIN, value);
        fflush(stdout);
        value = (value + 1) % PWM_RANGE;
        time_sleep(SLEEP_SEC);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CONSUMER    "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(TRIGGER)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(ECHO)");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(TRIGGER)");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, CONSUMER) < 0) {
        perror("gpiod_line_request_input(ECHO)");
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            break;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trigger, 1)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trigger, 0)");
            break;
        }

        /* Wait for echo rising edge (timeout 1 s) */
        struct timespec ts = {1, 0};
        int val;
        int waited = 0;
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(ECHO)");
                break;
            }
            if (val == 1) {
                break;
            }
            if (waited == 0) {
                nanosleep(&ts, NULL);
                waited = 1;
            }
        }
        if (!running) break;
        if (val != 1) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        /* Measure echo high duration (timeout 1 s) */
        struct timespec t_start, t_end;
        clock_gettime(CLOCK_MONOTONIC, &t_start);
        waited = 0;
        while (running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                perror("gpiod_line_get_value(ECHO)");
                break;
            }
            if (val == 0) {
                break;
            }
            if (waited == 0) {
                nanosleep(&ts, NULL);
                waited = 1;
            }
        }
        if (!running) break;
        if (val != 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        clock_gettime(CLOCK_MONOTONIC, &t_end);
        long long elapsed_ns = (t_end.tv_sec - t_start.tv_sec) * 1000000000LL +
                              (t_end.tv_nsec - t_start.tv_nsec);
        double distance = elapsed_ns / 2000000.0; /* speed of sound 343 m/s */

        if (distance < 2.0 || distance > 400.0) {
            fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
            break;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        /* Sleep 60 s, but wake early on signal */
        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28
#define CONFIG_REG     0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE    3.3f
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_init(int fd) {
    /* MUX=AIN0(GND), PGA=4.096V, MODE=Single, DR=128SPS, COMP=disabled */
    uint16_t cfg = 0x4000 | 0x0200 | 0x0100 | 0x0080 | 0x0003;
    return i2c_write_reg16(fd, CONFIG_REG, cfg);
}

static int ads1115_read(int fd, float *voltage) {
    uint16_t raw;
    if (i2c_read_reg16(fd, CONVERSION_REG, &raw) < 0)
        return -1;
    int16_t signed_raw = (int16_t)raw;
    *voltage = (float)signed_raw * REF_VOLTAGE / 32768.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "ADS1115 init failed (device may be absent)\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADS1115 initialized at 0x%02X on %s. Sampling every %d s.\n",
           ADS1115_ADDR, I2C_BUS, SAMPLE_PERIOD);

    while (g_running) {
        float voltage;
        if (ads1115_read(fd, &voltage) < 0) {
            fprintf(stderr, "Read failed; continuing.\n");
        } else {
            printf("Voltage: %.4f V\n", voltage);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define DELAY_SECONDS 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop: toggle once per second, exit on signal */
    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        sleep(DELAY_SECONDS);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE_OFFSET);
        fflush(stdout);

        sleep(DELAY_SECONDS);
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

