#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40
#define I2C_BUS "/dev/i2c-1"
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUM_HOLD 0xE5
#define MEASURE_TEMP_NO_HOLD 0xF6
#define MEASURE_HUM_NO_HOLD 0xF5
#define MEASURE_BOTH_NO_HOLD 0xF3
#define CONVERSION_DELAY_MS 20

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    usleep(CONVERSION_DELAY_MS * 1000);
    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, 2) < 0) return -1;
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int read_temperature(int fd, float *temp) {
    uint16_t raw;
    if (read_measurement(fd, MEASURE_TEMP_NO_HOLD, &raw) < 0) return -1;
    *temp = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static int read_humidity(int fd, float *hum) {
    uint16_t raw;
    if (read_measurement(fd, MEASURE_HUM_NO_HOLD, &raw) < 0) return -1;
    *hum = (125.0f * raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    printf("SI7021 sensor reader started. Press Ctrl+C to exit.\n");

    while (running) {
        float temp, hum;
        if (read_temperature(fd, &temp) < 0) {
            fprintf(stderr, "Error reading temperature.\n");
        } else if (read_humidity(fd, &hum) < 0) {
            fprintf(stderr, "Error reading humidity.\n");
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        }
        sleep(5);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

