    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    uint8_t config[3];
    config[0] = CONFIG_REG;
    config[1] = 0xC0; // AIN0 single-ended, 4.096V, 128 SPS, continuous
    config[2] = 0x83; // MSB of config register

    if (write(fd, config, 3) != 3) {
        fprintf(stderr, "Error writing config to ADS1115: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3; i++) {
        uint8_t reg = CONVERSION_REG;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting conversion register: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        uint8_t data[2];
        if (read(fd, data, 2) != 2) {
            fprintf(stderr, "Error reading conversion data: %s\n", strerror(errno));
            close(fd);
            return 1;
        }

        int16_t raw = (int16_t)((data[0] << 8) | data[1]);
        printf("Reading %d: %d\n", i + 1, raw);
        sleep(1);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_PINS 6
#define NUM_CYCLES 256

static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int values[NUM_PINS] = {0, 1, 0, 1, 0, 1};
    int i, ret;

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_PINS; i++) {
        ret = gpiod_line_request_output(lines[i], "digital_output", 0);
        if (ret < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %u: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting digital output on GPIO 8, 9, 10, 11, 23, 24. Press Ctrl+C to exit.\n");

    for (i = 0; i < NUM_CYCLES && running; i++) {
        for (int j = 0; j < NUM_PINS; j++) {
            ret = gpiod_line_set_value(lines[j], values[j]);
            if (ret < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for pin %u: %s\n",
                        pins[j], strerror(errno));
                goto cleanup;
            }
        }
        printf("Cycle %d: GPIO 8=%d, GPIO 9=%d, GPIO 10=%d, GPIO 11=%d, GPIO 23=%d, GPIO 24=%d\n",
               i + 1, values[0], values[1], values[2], values[3], values[4], values[5]);
        usleep(10000);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    for (i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

