#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4    4
#define GPIO_5    5
#define PERIOD_US 500000  /* 0.5 seconds */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line5 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line(GPIO_4)");
        goto cleanup;
    }
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    if (!line5) {
        perror("gpiod_chip_get_line(GPIO_5)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line4, "blink4", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_4)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line5, "blink5", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_5)");
        goto cleanup;
    }

    /* Main loop: toggle each line every 0.5 s, report state */
    while (running) {
        /* GPIO 4 -> HIGH */
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_4)");
            break;
        }
        printf("GPIO 4 -> HIGH\n");
        fflush(stdout);
        usleep(PERIOD_US);

        if (!running) break;

        /* GPIO 4 -> LOW */
        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_4)");
            break;
        }
        printf("GPIO 4 -> LOW\n");
        fflush(stdout);
        usleep(PERIOD_US);

        if (!running) break;

        /* GPIO 5 -> HIGH */
        ret = gpiod_line_set_value(line5, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_5)");
            break;
        }
        printf("GPIO 5 -> HIGH\n");
        fflush(stdout);
        usleep(PERIOD_US);

        if (!running) break;

        /* GPIO 5 -> LOW */
        ret = gpiod_line_set_value(line5, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_5)");
            break;
        }
        printf("GPIO 5 -> LOW\n");
        fflush(stdout);
        usleep(PERIOD_US);
    }

cleanup:
    /* Release lines and close chip on every exit path */
    if (line4) gpiod_line_release(line4);
    if (line5) gpiod_line_release(line5);
    if (chip)  gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

