#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_8  8
#define GPIO_9  9
#define GPIO_10 10
#define GPIO_11 11

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {GPIO_8, GPIO_9, GPIO_10, GPIO_11};
    int i;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], "digital_output", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], i % 2) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO %d=%d, GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               GPIO_8,  (i % 2),
               GPIO_9,  (i % 2),
               GPIO_10, (i % 2),
               GPIO_11, (i % 2));
        fflush(stdout);
        usleep(100000);
    }

cleanup:
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

