/*
 * HC-SR04 ultrasonic distance sensor reader using libgpiod.
 *
 * Wiring (Raspberry Pi 40-pin header, BCM numbering):
 *   GPIO 17 -> HC-SR04 TRIG (physical pin 11)
 *   GPIO 18 -> HC-SR04 ECHO (physical pin 12)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lgpiod
 *
 * Run:
 *   ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

#include <gpiod.h>

#define TRIG_PIN      17
#define ECHO_PIN      18
#define CHIP_NAME     "gpiochip4"   /* BCM GPIO bank on Pi 5; use "gpiochip0" on Pi 3/4 */

#define TRIG_PULSE_US 10           /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US 300000     /* 300 ms timeout for echo */
#define POLL_INTERVAL_S 1          /* 1 second between readings */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns:
 *   > 0  : pulse width in us
 *   -1   : timeout (no echo received)
 *   -2   : GPIO read error
 */
static long measure_echo(struct gpiod_line *echo_line)
{
    struct timespec t0, t1;
    int val;

    /* Wait for echo to go HIGH (response start) */
    while (1) {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            return -2;
        }
        if (val == 1) {
            break;
        }
        if (!g_running) {
            return -1;
        }
        usleep(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &t0);

    /* Wait for echo to go LOW (response end) */
    while (1) {
        val = gpiod_line_get_value(echo_line);
        if (val < 0) {
            return -2;
        }
        if (val == 0) {
            break;
        }
        if (!g_running) {
            return -1;
        }
        usleep(10);
    }

    clock_gettime(CLOCK_MONOTONIC, &t1);

    long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000L +
                      (t1.tv_nsec - t0.tv_nsec) / 1000L;

    if (elapsed_us > ECHO_TIMEOUT_US) {
        return -1;  /* timeout */
    }

    return elapsed_us;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig_line = NULL;
    struct gpiod_line *echo_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        /* Fallback: try opening by label */
        chip = gpiod_chip_open_by_label(CHIP_NAME);
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_lookup(CHIP_NAME);
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig_line = gpiod_chip_get_line(chip, TRIG_PIN);
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (trig_line == NULL || echo_line == NULL) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request TRIG as output, initial value LOW */
    if (gpiod_line_request_output(trig_line, "hcsr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request TRIG line as output: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Request ECHO as input */
    if (gpiod_line_request_input(echo_line, "hcsr04-echo") < 0) {
        fprintf(stderr, "Failed to request ECHO line as input: %s\n",
                strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ready. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n",
           TRIG_PIN, ECHO_PIN);

    while (g_running) {
        /* Ensure trigger is LOW before pulsing */
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set TRIG LOW: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig_line, 1) < 0) {
            fprintf(stderr, "Failed to set TRIG HIGH: %s\n", strerror(errno));
            break;
        }
        usleep(TRIG_PULSE_US);
        if (gpiod_line_set_value(trig_line, 0) < 0) {
            fprintf(stderr, "Failed to set TRIG LOW: %s\n", strerror(errno));
            break;
        }

        long pulse_us = measure_echo(echo_line);

        if (pulse_us > 0) {
            /* Speed of sound ~343 m/s => 1 us = 0.0343 cm
             * distance = (pulse_us * 0.0343) / 2 */
            float distance = (float)pulse_us * 0.0343f / 2.0f;
            printf("Distance: %.2f cm\n", distance);
        } else if (pulse_us == -2) {
            fprintf(stderr, "Error reading echo pin.\n");
        } else {
            fprintf(stderr, "No echo received (timeout or device absent).\n");
        }

        /* Sleep 1 second, but wake early on signal */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);  /* 100 ms */
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on all exit paths */
    if (trig_line != NULL) {
        gpiod_line_release(trig_line);
    }
    if (echo_line != NULL) {
        gpiod_line_release(echo_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

