#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600
#define READ_BUF_SIZE 256

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int setup_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int init_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag &= ~(PARENB | PARODD);
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_oflag &= ~OPOST;
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 5;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void cleanup(int fd) {
    if (fd != -1) {
        close(fd);
    }
}

int main(void) {
    if (setup_signal_handler() != 0) {
        return EXIT_FAILURE;
    }

    int fd = init_serial(SERIAL_PORT, BAUD_RATE);
    if (fd == -1) {
        fprintf(stderr, "Error: Could not initialize serial port %s: %s\n",
                SERIAL_PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Serial port %s initialized. Reading data...\n", SERIAL_PORT);

    char read_buf[READ_BUF_SIZE];
    ssize_t bytes_read;

    while (g_running) {
        bytes_read = read(fd, read_buf, sizeof(read_buf) - 1);
        if (bytes_read > 0) {
            read_buf[bytes_read] = '\0';
            printf("Received: %s", read_buf);
            fflush(stdout);
        } else if (bytes_read == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("read");
            break;
        } else {
            usleep(100000);
            continue;
        }
    }

    printf("\nExiting...\n");
    cleanup(fd);
    return EXIT_SUCCESS;
}

