        perror("gpiod_line_request_output (GPIO 22)");
        cleanup_resources();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(line_27, "digital_output", 0) < 0) {
        perror("gpiod_line_request_output (GPIO 27)");
        cleanup_resources();
        return EXIT_FAILURE;
    }

    int values[] = {1, 0, 1, 0};
    for (int i = 0; i < 4; i++) {
        if (gpiod_line_set_value(line_4, values[i]) < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
