#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define DHT11_CONSUMER "dht11"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_us) {
    int elapsed = 0;
    while (g_running) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            return -1;
        }
        if (val == level) {
            return elapsed;
        }
        sleep_us(1);
        elapsed++;
        if (elapsed >= timeout_us) {
            return -2;
        }
    }
    return -3;
}

static int read_dht11(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0, 0, 0, 0, 0};
    int i;

    if (gpiod_line_request_output(line, DHT11_CONSUMER, 0) < 0) {
        return -1;
    }
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    sleep_us(30);
    if (gpiod_line_request_input(line, DHT11_CONSUMER) < 0) {
        return -1;
    }

    int t0 = wait_for_level(line, 0, 100);
    if (t0 < 0) return -1;
    int t1 = wait_for_level(line, 1, 100);
    if (t1 < 0) return -1;
    int t2 = wait_for_level(line, 0, 100);
    if (t2 < 0) return -1;

    for (i = 0; i < 40; i++) {
        int t3 = wait_for_level(line, 1, 100);
        if (t3 < 0) return -1;
        int t4 = wait_for_level(line, 0, 100);
        if (t4 < 0) return -1;
        data[i / 8] <<= 1;
        if (t4 > 40) {
            data[i / 8] |= 1;
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        return -2;
    }

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        *temp = -*temp;
    }

    if (*temp < 0.0f || *temp > 80.0f || *hum < 0.0f || *hum > 100.0f) {
        return -3;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp = 0.0f, hum = 0.0f;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (read_dht11(line, &temp, &hum) == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        rc = EXIT_SUCCESS;
    } else {
        fprintf(stderr, "DHT11 read failed (device absent or bus error)\n");
    }

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

