    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
