                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);

    /* Clean shutdown on exit */
    atexit(gpiod_line_release);
    atexit(gpiod_chip_close);

    /* Wait for signal or completion */
    while (running) {
        pause();
    }

    return EXIT_SUCCESS;
}

