#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_DIR_FORMAT "%s/w1_slave"
#define MAX_PATH_LENGTH 256
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *device_path, float *temperature) {
    char path[MAX_PATH_LENGTH];
    int ret = snprintf(path, sizeof(path), W1_SLAVE_DIR_FORMAT, device_path);
    if (ret < 0 || (size_t)ret >= sizeof(path)) {
        fprintf(stderr, "Error: path too long\n");
        return -1;
    }

    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256];
    char line2[256];

    if (!fgets(line1, sizeof(line1), fp) || !fgets(line2, sizeof(line2), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Error: sensor not present or not responding\n");
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (!temp_str) {
        fprintf(stderr, "Error: temperature field not found\n");
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    if (temp_raw == 0 && errno == EINVAL) {
        fprintf(stderr, "Error: invalid temperature value\n");
        return -1;
    }

    *temperature = (float)temp_raw / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    char devices_dir[] = W1_DEVICES_DIR;
    if (chdir(devices_dir) == -1) {
        fprintf(stderr, "Error changing directory to %s: %s\n", devices_dir, strerror(errno));
        return 1;
    }

    if (access(W1_DEVICES_DIR, F_OK) != 0) {
        fprintf(stderr, "Error: %s does not exist. Is the w1-gpio kernel module loaded?\n", W1_DEVICES_DIR);
        return 1;
    }

    char device_path[MAX_PATH_LENGTH];
    struct dirent *dir;
    int found = 0;

    while (running) {
        if (found) break;

        if (snprintf(device_path, sizeof(device_path), "%s/28-00000", W1_DEVICES_DIR) >= (int)sizeof(device_path)) {
            fprintf(stderr, "Error: device path too long\n");
            break;
        }

        if (access(device_path, F_OK) == 0) {
            found = 1;
        } else {
            fprintf(stderr, "Error: %s does not exist. Waiting 5 seconds...\n", device_path);
            sleep(5);
            continue;
        }
    }

    if (!found) {
        fprintf(stderr, "Error: No DS18B20 sensor found. Exiting.\n");
        return 1;
    }

    printf("Found DS18B20 sensor at %s\n", device_path);

    while (running) {
        float temperature;
        if (read_temperature(device_path, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }
        sleep(5);
    }

    printf("\nExiting cleanly.\n");
    return 0;
}

