#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5
#define TRIGGER_SOFT_RESET 0xFE

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int htu21d_reset(int fd) {
    if (i2c_write_byte(fd, TRIGGER_SOFT_RESET) < 0) return -1;
    usleep(15000);
    return 0;
}

static int htu21d_read_measurement(int fd, uint8_t cmd, uint16_t *raw) {
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    usleep(5000);

    uint8_t buf[3];
    if (i2c_read_bytes(fd, buf, 3) < 0) return -1;

    if (buf[0] & 0x80) {
        fprintf(stderr, "HTU21D measurement error: 0x%02X\n", buf[0]);
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static float convert_temperature(uint16_t raw) {
    return -46.85 + 175.72 * ((float)raw / 65536.0);
}

static float convert_humidity(uint16_t raw) {
    float h = -6.0 + 125.0 * ((float)raw / 65536.0);
    if (h < 0.0) h = 0.0;
    if (h > 100.0) h = 100.0;
    return h;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", HTU21D_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }

    if (htu21d_reset(i2c_fd) < 0) {
        fprintf(stderr, "HTU21D not responding at 0x%02X\n", HTU21D_ADDR);
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t raw_t, raw_h;

        if (htu21d_read_measurement(i2c_fd, TRIGGER_TEMP_MEASURE, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed\n");
        } else if (htu21d_read_measurement(i2c_fd, TRIGGER_HUMID_MEASURE, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed\n");
        } else {
            float temp = convert_temperature(raw_t);
            float hum = convert_humidity(raw_h);
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
            fflush(stdout);
        }

        for (int i = 0; i < 60 && running; i++) {
            sleep(1);
        }
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nExiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4    4
#define GPIO_18   18
#define PERIOD_US 50000  /* 50 ms */

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL, *line18 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line(GPIO_4)");
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line(GPIO_18)");
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line4, "gpio4_out", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_4)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line18, "gpio18_out", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_18)");
        goto cleanup;
    }

    /* Main loop: toggle both lines every 50 ms until interrupted */
    while (running) {
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_4)");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_18)");
            break;
        }
        usleep(PERIOD_US);

        if (!running) break;

        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_4)");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_18)");
            break;
        }
        usleep(PERIOD_US);
    }

    /* Ensure outputs are LOW on exit */
    gpiod_line_set_value(line4, 0);
    gpiod_line_set_value(line18, 0);

cleanup:
    /* Release lines and close chip */
    if (line4) gpiod_line_release(line4);
    if (line18) gpiod_line_release(line18);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

