#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN_1 17
#define DHT22_PIN_2 22
#define DHT22_PIN_3 23
#define DHT22_PIN_4 24

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_dht22(struct gpiod_line *line) {
    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int counter = 0;
    int j = 0, i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    usleep(20000);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    for (i = 0; i < 85; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate) {
            counter++;
            usleep(1);
            if (counter == 255) return -1;
        }
        laststate = gpiod_line_get_value(line);
        if (counter == 0) continue;
        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16)
                data[j / 8] |= 1;
            j++;
        }
    }

    if (j == 40) {
        int checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
        if (data[4] == checksum) {
            float h = (float)((data[0] << 8) + data[1]) / 10.0f;
            float t = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0f;
            if (data[2] & 0x80) t = -t;
            printf("Temperature: %.1f C, Humidity: %.1f %%\n", t, h);
            return 0;
        }
    }
    return -1;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {DHT22_PIN_1, DHT22_PIN_2, DHT22_PIN_3, DHT22_PIN_4};
    int i;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < 4; i++) {
            if (read_dht22(lines[i]) != 0) {
                fprintf(stderr, "Error reading DHT22 on pin %d\n", pins[i]);
            }
        }
        sleep(2);
    }

cleanup:
    for (i = 0; i < 4; i++) {
        if (lines[i]) gpiod_line_release(lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SLEEP_SEC 0.5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int values[3] = {0, 0, 0};
    int idx = 0;
    int step = 10;

    while (running) {
        values[idx] += step;
        if (values[idx] >= PWM_RANGE) {
            values[idx] = PWM_RANGE;
            step = -10;
        } else if (values[idx] <= 0) {
            values[idx] = 0;
            step = 10;
        }

        if (gpioPWM(PWM_PIN_1, values[0]) != 0 ||
            gpioPWM(PWM_PIN_2, values[1]) != 0 ||
            gpioPWM(PWM_PIN_3, values[2]) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }

        printf("PWM 1: %d, PWM 2: %d, PWM 3: %d\n", values[0], values[1], values[2]);
        fflush(stdout);

        sleep(SLEEP_SEC);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(GPIO_17)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(GPIO_27)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line17, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_17)");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line27, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_27)");
        goto cleanup;
    }

    /* Main loop: toggle once per second, report, until interrupted */
    while (running) {
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_17)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_17);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_17)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_17);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        ret = gpiod_line_set_value(line27, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_27)");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_27);
        fflush(stdout);

        sleep(1);

        if (!running) break;

        ret = gpiod_line_set_value(line27, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_27)");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_27);
        fflush(stdout);
    }

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) gpiod_line_release(line17);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);

    return (running) ? EXIT_FAILURE : EXIT_SUCCESS;
}

