#define SSD1306_I2C_ADDR 0x3C
#define SSD1306_WIDTH 128
#define SSD1306_HEIGHT 64
#define SSD1306_PAGES (SSD1306_HEIGHT / 8)

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(uint8_t *buf, size_t len) {
    if (write(i2c_fd, buf, len) != (ssize_t)len) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

static int ssd1306_command(uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    return i2c_write(buf, 2);
}

static int ssd1306_init(void) {
    uint8_t init_cmds[] = {
        0xAE, 0xD5, 0x80, 0xA8, 0x3F, 0xD3, 0x00, 0x40,
        0x8D, 0x14, 0x20, 0x00, 0xA1, 0xC8, 0xDA, 0x12,
        0x81, 0xCF, 0xD9, 0xF1, 0xDB, 0x40, 0xA4, 0xA6, 0xAF
    };
    return i2c_write(init_cmds, sizeof(init_cmds));
}

static int ssd1306_clear(void) {
    uint8_t buf[SSD1306_WIDTH * 2];
    for (int i = 0; i < SSD1306_WIDTH; i++) {
        buf[i * 2]     = 0x00;
        buf[i * 2 + 1] = 0x00;
    }
    return i2c_write(buf, sizeof(buf));
}

static int ssd1306_display_text(int page, const char *text) {
    if (page < 0 || page >= SSD1306_PAGES) return -1;
    uint8_t buf[SSD1306_WIDTH * 2];
    for (int i = 0; i < SSD1306_WIDTH; i++) {
        buf[i * 2]     = 0x00;
        buf[i * 2 + 1] = 0x00;
    }
    int idx = 0;
    for (int col = 0; col < SSD1306_WIDTH && text[idx] != '\0'; col++) {
        uint8_t c = (uint8_t)text[idx++];
        if (c >= 32 && c <= 126) {
            uint8_t glyph[5] = {0x00, 0x00, 0x00, 0x00, 0x00};
            glyph[0] = 0x40 | (col & 0x0F);
            glyph[1] = 0x40 | ((col + 16) & 0x0F);
            glyph[2] = (c < 0x7F) ? 0x44 : 0x48;
            glyph[3] = 0x00;
            glyph[4] = 0x00;
            buf[col * 2]     = glyph[0];
            buf[col * 2 + 1] = glyph[1];
        }
    }
    uint8_t page_cmd = 0xB0 | (page & 0x07);
    if (ssd1306_command(page_cmd) < 0) return -1;
    if (ssd1306_command(0x21) < 0) return -1;
    if (ssd1306_command(0x00) < 0) return -1;
