#include <signal.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL, *line5 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line5 = gpiod_chip_get_line(chip, GPIO_5);
    if (!line2 || !line3 || !line5) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line3, CONSUMER, 0) < 0 ||
        gpiod_line_request_output(line5, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line2, 1) < 0 ||
            gpiod_line_set_value(line3, 1) < 0 ||
            gpiod_line_set_value(line5, 1) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO 2, 3, 5 set HIGH\n");
        fflush(stdout);
        sleep(5);

        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0 ||
            gpiod_line_set_value(line3, 0) < 0 ||
            gpiod_line_set_value(line5, 0) < 0) {
            perror("gpiod_line_set_value");
            goto cleanup;
        }
        printf("GPIO 2, 3, 5 set LOW\n");
        fflush(stdout);
        sleep(5);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line5) gpiod_line_release(line5);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

