#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_ADDR 0x3F
#define I2C_DEV "/dev/i2c-1"

static int i2c_fd = -1;

void cleanup_and_exit(int signum) {
    (void)signum;
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(0);
}

int i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

int hd44780_command(int fd, unsigned char cmd) {
    return i2c_write_byte(fd, 0x00); // Data bit = 0
}

int hd44780_data(int fd, unsigned char data) {
    return i2c_write_byte(fd, 0x01); // Data bit = 1
}

int hd44780_init(int fd) {
    usleep(50000); // Wait > 40ms after power-on
    if (i2c_write_byte(fd, 0x30) < 0) return -1; // Function set: 4-bit
    usleep(4500);
    if (i2c_write_byte(fd, 0x30) < 0) return -1;
    usleep(150);
    if (i2c_write_byte(fd, 0x30) < 0) return -1;
    if (i2c_write_byte(fd, 0x20) < 0) return -1; // Function set: 8-bit
    if (i2c_write_byte(fd, 0x28) < 0) return -1; // 2 lines, 5x8 font
    if (i2c_write_byte(fd, 0x08) < 0) return -1; // Display off
    if (i2c_write_byte(fd, 0x01) < 0) return -1; // Clear display
    usleep(2000);
    if (i2c_write_byte(fd, 0x06) < 0) return -1; // Entry mode: increment
    if (i2c_write_byte(fd, 0x0C) < 0) return -1; // Display on, cursor off, blink off
    return 0;
}

int hd44780_clear(int fd) {
    if (hd44780_command(fd, 0x01) < 0) return -1;
    usleep(2000);
    return 0;
}

int hd44780_set_cursor(int fd, int row, int col) {
    unsigned char addr = 0x80 | (row * 0x40) + col;
    if (hd44780_command(fd, 0x80) < 0) return -1;
    if (hd44780_data(fd, addr) < 0) return -1;
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup_and_exit;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (hd44780_init(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize HD44780\n");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        if (hd44780_clear(i2c_fd) < 0) break;
        if (hd44780_set_cursor(i2c_fd, 0, 0) < 0) break;
        if (hd44780_data(i2c_fd, 'T') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'm') < 0) break;
        if (hd44780_data(i2c_fd, 'p') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'r') < 0) break;
        if (hd44780_data(i2c_fd, ':') < 0) break;
        if (hd44780_set_cursor(i2c_fd, 1, 0) < 0) break;
        if (hd44780_data(i2c_fd, 'T') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'm') < 0) break;
        if (hd44780_data(i2c_fd, 'p') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'r') < 0) break;
        if (hd44780_data(i2c_fd, ':') < 0) break;
        if (hd44780_set_cursor(i2c_fd, 2, 0) < 0) break;
        if (hd44780_data(i2c_fd, 'T') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'm') < 0) break;
        if (hd44780_data(i2c_fd, 'p') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'r') < 0) break;
        if (hd44780_data(i2c_fd, ':') < 0) break;
        if (hd44780_set_cursor(i2c_fd, 3, 0) < 0) break;
        if (hd44780_data(i2c_fd, 'T') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'm') < 0) break;
        if (hd44780_data(i2c_fd, 'p') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'r') < 0) break;
        if (hd44780_data(i2c_fd, ':') < 0) break;
        if (hd44780_set_cursor(i2c_fd, 4, 0) < 0) break;
        if (hd44780_data(i2c_fd, 'T') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'm') < 0) break;
        if (hd44780_data(i2c_fd, 'p') < 0) break;
        if (hd44780_data(i2c_fd, 'e') < 0) break;
        if (hd44780_data(i2c_fd, 'r') < 0) break;
        if (hd44780_data(i2c_fd, ':') < 0) break;

        sleep(10);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return 1;
}

