}

static int init_mpu6050(int fd) {
    uint8_t whoami;
    if (i2c_read_reg(fd, 0x75, &whoami) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %s\n", strerror(errno));
        return -1;
    }
    if (whoami != 0x68) {
        fprintf(stderr, "WHO_AM_I mismatch: 0x%02X (expected 0x68)\n", whoami);
        return -1;
    }
    if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
    if (whoami & 0x40) {
        if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
        if (whoami & 0x40) {
            if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
            if (whoami & 0x40) {
                if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                if (whoami & 0x40) {
                    if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                    if (whoami & 0x40) {
                        if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                        if (whoami & 0x40) {
                            if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                            if (whoami & 0x40) {
                                if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                if (whoami & 0x40) {
                                    if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                    if (whoami & 0x40) {
                                        if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                        if (whoami & 0x40) {
                                            if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                            if (whoami & 0x40) {
                                                if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                                if (whoami & 0x40) {
                                                    if (i2c_read_reg(fd, PWR_MGMT_1, &whoami) < 0) return -1;
                                                    if (whoami & 0x40) {
