static int read_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, ACCEL_XOUT_H, buf, 6) < 0) return -1;
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (init_mpu6050(fd) < 0) {
        fprintf(stderr, "Error initializing MPU6050\n");
        close(fd);
        return 1;
    }

    int16_t ax, ay, az;
    for (int i = 0; i < 100 && running; i++) {
        if (read_accel(fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
            break;
        }
        printf("Accel X: %6d, Y: %6d, Z: %6d\n", ax, ay, az);
        usleep(100000);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_PIN_1 14
#define GPIO_PIN_2 15
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, GPIO_PIN_1);
    if (!line1) {
        perror("gpiod_chip_get_line(GPIO_PIN_1)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_PIN_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_PIN_2)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line1, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO_PIN_1)");
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(GPIO_PIN_2)");
        goto cleanup;
    }

    while (running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN_1, strerror(errno));
            goto cleanup;
        }
        if (val2 < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN_2, strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_set_value(line1, val1) < 0) {
            perror("gpiod_line_set_value(GPIO_PIN_1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, val2) < 0) {
            perror("gpiod_line_set_value(GPIO_PIN_2)");
            goto cleanup;
        }

        printf("GPIO %d: %d, GPIO %d: %d\n", GPIO_PIN_1, val1, GPIO_PIN_2, val2);
        fflush(stdout);

        for (int i = 0; i < 50 && running; i++) {
            usleep(100000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <stdbool.h>
#include <sys/time.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor_data"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static MQTTClient client;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_mqtt(void) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS,
                                MQTT_CLIENT_ID,
                                MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_create failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }

    if ((rc = MQTTClient_setCallbacks(client, NULL, NULL, NULL, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_setCallbacks failed: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return -1;
    }

    return 0;
}

static int connect_to_broker(void) {
    int rc;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_connect failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static int publish_message(const char *message) {
    int rc;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token = 0;

    pubmsg.payload = (void *)message;
    pubmsg.payloadlen = (int)strlen(message);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: MQTTClient_publishMessage failed: %s\n", MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

static int read_sensor_data(int *temperature, int *humidity) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    long long current_time = (long long)tv.tv_sec * 1000 + tv.tv_usec / 1000;

    *temperature = (int)(current_time % 100);
    *humidity = (int)((current_time / 10) % 100);
    return 0;
}

static int validate_sensor_data(int temperature, int humidity) {
    if (temperature < 0 || temperature > 100 || humidity < 0 || humidity > 100) {
        fprintf(stderr, "Error: Invalid sensor data (Temperature: %d, Humidity: %d)\n", temperature, humidity);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
}

int main(void) {
    int temperature, humidity;
    int retries = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_mqtt() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (connect_to_broker() != 0) {
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            if (validate_sensor_data(temperature, humidity) == 0) {
                char message[50];
                snprintf(message, sizeof(message), "Temperature: %d, Humidity: %d", temperature, humidity);
                if (publish_message(message) != 0) {
                    fprintf(stderr, "Error: Failed to publish message\n");
                } else {
                    printf("Published: %s\n", message);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        if (retries < MAX_RETRIES) {
            gpioDelay(RETRY_DELAY_US);
            retries++;
        } else {
            fprintf(stderr, "Error: Max retries reached. Exiting.\n");
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 23
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (running) {
        int value = rand() % 2;  /* 0 or 1 */
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }
        printf("GPIO %d set to %d\n", GPIO_PIN, value);
        fflush(stdout);
        sleep(5);
    }

    /* Clean up: set line LOW and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    22
#define TRIGGER2_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *trig2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig  = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo  = gpiod_chip_get_line(chip, ECHO_PIN);
    trig2 = gpiod_chip_get_line(chip, TRIGGER2_PIN);
    if (!trig || !echo || !trig2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hcsr04-trig", 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_output(trig2, "hcsr04-trig2", 0) < 0) {
        perror("gpiod_line_request_output(trig2)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        sleep_us(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        unsigned int timeout = 0;
        int val;
        while (running && (val = gpiod_line_get_value(echo)) < 0) {
            perror("gpiod_line_get_value(echo)");
            break;
        }
        if (!running) break;

        if (val == 1) {
            timeout = 0;
            while (running && (val = gpiod_line_get_value(echo)) < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (!running) break;

            if (val == 0) {
                timeout = 0;
                while (running && (val = gpiod_line_get_value(echo)) < 0) {
                    perror("gpiod_line_get_value(echo)");
                    break;
                }
                if (!running) break;

                if (val == 1) {
                    unsigned int pulse_us = timeout;
                    if (pulse_us > 0 && pulse_us < 100000) {
                        printf("Distance: %u us\n", pulse_us);
                    } else {
                        printf("Distance: out of range (%u us)\n", pulse_us);
                    }
                } else {
                    printf("Distance: timeout\n");
                }
            } else {
                printf("Distance: echo stuck high\n");
            }
        } else {
            printf("Distance: echo stuck low\n");
        }

        sleep_us(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig)  gpiod_line_release(trig);
    if (echo)  gpiod_line_release(echo);
    if (trig2) gpiod_line_release(trig2);
    if (chip)  gpiod_chip_close(chip);
    return ret;
}

