#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_KEEPALIVE 60
#define MQTT_QOS 1
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(void) {
    int sensor_value = gpioRead(4);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    return sensor_value;
}

static int format_sensor_data(int sensor_value, char *buffer, size_t buffer_size) {
    struct timeval tv;
    struct tm tm_info;
    char timestamp[32];

    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        return -1;
    }

    localtime_r(&tv.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    snprintf(buffer, buffer_size, "%s.%06ld, Sensor Value: %d", timestamp, tv.tv_usec, sensor_value);
    return 0;
}

static int publish_mqtt_message(const char *message) {
    int rc = mqtt_publish(mqtt_client, MQTT_TOPIC, message, MQTT_QOS, 0);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "Error publishing MQTT message: %s\n", mqtt_strerror(rc));
        return -1;
    }
    return 0;
}

int main(void) {
    int rc;
    char sensor_data_string[256];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(4, PI_INPUT);

    mqtt_client = mqtt_create_client(MQTT_CLIENT_ID);
    if (mqtt_client == NULL) {
        fprintf(stderr, "Error creating MQTT client\n");
        gpioTerminate();
        return 1;
    }

    rc = mqtt_connect(mqtt_client, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MQTT_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mqtt_strerror(rc));
        mqtt_destroy_client(mqtt_client);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int sensor_value = read_sensor_data();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor data, exiting.\n");
            break;
        }

        if (format_sensor_data(sensor_value, sensor_data_string, sizeof(sensor_data_string)) != 0) {
            fprintf(stderr, "Error formatting sensor data, exiting.\n");
            break;
        }

        if (publish_mqtt_message(sensor_data_string) != 0) {
            fprintf(stderr, "Error publishing MQTT message, exiting.\n");
            break;
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    mqtt_disconnect(mqtt_client);
    mqtt_destroy_client(mqtt_client);
    gpioTerminate();

    return 0;
}

