static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_pigpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    return 0;
}

static int read_sensor_data(int *out_value) {
    if (!pigpio_initialized) {
        fprintf(stderr, "pigpio not initialized\n");
        return -1;
    }
    int value = gpioRead(4);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed: %s\n", strerror(errno));
        return -1;
    }
    *out_value = value;
    return 0;
}

static int validate_sensor_data(int value) {
    if (value < 0 || value > 1) {
        fprintf(stderr, "Invalid sensor data: %d\n", value);
        return -1;
    }
    return 0;
}

static int publish_data(int sensor_value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    MQTTClient_deliveryToken token;
    int rc = MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (pigpio_initialized) {
        gpioTerminate();
        pigpio_initialized = 0;
    }
    if (client) {
        MQTTClient_destroy(&client);
    }
}

