}

int read_ads1115(int handle, float *voltage, float *temperature) {
    char config[3];
    char reg[1] = {0x01};
    char data[2];
    int16_t raw;

    // Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous
    config[0] = 0xC1; // Bit 15: OS=1 (start), Bit 14: MUX=100 (AIN0), Bits 12-9: PGA=001 (+/-4.096V)
    config[1] = 0x83; // Bits 8-7: MODE=1 (continuous), Bits 6-5: DR=100 (128 SPS), Bits 4-3: COMP_MODE=00, Bits 2-1: COMP_POL=0, Bit 0: COMP_LAT=0
    config[2] = 0x00;

    if (i2cWriteI2CBlockData(handle, reg[0], config, 3) < 0) {
        fprintf(stderr, "Error writing config to ADS1115\n");
        return -1;
    }

    // Wait for conversion (128 SPS -> ~7.8ms, use 10ms for safety)
    gpioDelay(10000);

    // Read conversion register (0x00)
    if (i2cReadI2CBlockData(handle, 0x00, data, 2) < 0) {
        fprintf(stderr, "Error reading conversion from ADS1115\n");
        return -1;
    }

    raw = (data[0] << 8) | data[1];
    *voltage = (raw * 4.096) / 32768.0;
    *temperature = (*voltage * 100.0) - 50.0;

    return 0;
}

int main() {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    char payload[128];
    int result;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    MQTTClient_create(&client, MQTT_BROKER, MQTT_PORT, true, NULL);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    result = MQTTClient_connect(client, &conn_opts);
    if (result != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %d\n", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_READINGS && running; i++) {
        float voltage, temperature;
        if (read_ads1115(i2c_handle, &voltage, &temperature) == 0) {
            snprintf(payload, sizeof(payload), "{\"voltage\":%.3f,\"temperature\":%.3f}", voltage, temperature);
            result = MQTTClient_publishMessage(client, MQTT_TOPIC, payload, strlen(payload));
            if (result != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message: %d\n", result);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(1000000); // 1 second between readings
    }

    MQTTClient_disconnect(client, 1000);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

