}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_BROKER_ADDRESS "tcp://localhost:1883"
#define MQTT_CLIENT_ID "raspi_sensor_1"
#define MQTT_TOPIC "home/office/sensor1"
#define MQTT_QOS 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(void) {
    int sensor_value = gpioRead(4);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor: %s\n", strerror(errno));
        return -1;
    }
    return sensor_value;
}

static void format_sensor_data(int sensor_value, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer, buffer_size, "{\"sensor1\": %d, \"timestamp\": \"%s\"}", sensor_value, timestamp);
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    char payload[256];
    int rc;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(4, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO 4 as input\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((rc = MQTTClient_create(&client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int sensor_value = read_sensor_data();
        if (sensor_value >= 0) {
            format_sensor_data(sensor_value, payload, sizeof(payload));
            printf("Publishing: %s\n", payload);
            if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, payload, strlen(payload), MQTT_QOS, NULL, NULL)) != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message, return code %d\n", rc);
            }
        } else {
            fprintf(stderr, "Sensor read failed, retrying...\n");
        }
        sleep(5);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return EXIT_SUCCESS;
}

