#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define CAPTURE_INTERVAL 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_image(int fd, const char *filename) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        fprintf(stderr, "VIDIOC_S_FMT failed: %s\n", strerror(errno));
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_JPEG) {
        fprintf(stderr, "Device does not support JPEG capture\n");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "VIDIOC_REQBUFS failed: %s\n", strerror(errno));
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QUERYBUF failed: %s\n", strerror(errno));
        return -1;
    }

    void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "mmap failed: %s\n", strerror(errno));
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        munmap(buffer, buf.length);
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s: %s\n", filename, strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        return -1;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    fclose(fp);

    if (written != buf.bytesused) {
        fprintf(stderr, "Failed to write entire buffer\n");
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        xioctl(fd, VIDIOC_STREAMOFF, &type);
        munmap(buffer, buf.length);
        return -1;
    }

    xioctl(fd, VIDIOC_STREAMOFF, &type);
    munmap(buffer, buf.length);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Failed to open %s: %s\n", DEVICE_NAME, strerror(errno));
        return 1;
    }

    struct stat st;
    if (stat(DEVICE_NAME, &st) == -1) {
        fprintf(stderr, "Device %s does not exist: %s\n", DEVICE_NAME, strerror(errno));
        close(fd);
        return 1;
    }

    if (!S_ISCHR(st.st_mode)) {
        fprintf(stderr, "Device %s is not a character device\n", DEVICE_NAME);
        close(fd);
        return 1;
    }

    while (running) {
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%ld.jpg", (long)time(NULL));

        if (capture_image(fd, filename) == 0) {
            printf("Image saved to %s\n", filename);
        } else {
            fprintf(stderr, "Failed to capture image\n");
        }

        sleep(CAPTURE_INTERVAL);
    }

    if (close(fd) == -1) {
        fprintf(stderr, "Failed to close device: %s\n", strerror(errno));
        return 1;
    }

    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FILENAME "image.jpg"

static int fd = -1;
static void *buffer = NULL;

static void cleanup(void) {
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, 16384);
        buffer = NULL;
    }
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

static int xioctl(int fh, int request, void *arg) {
    int r;
    do {
        r = ioctl(fh, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned char *start;
    unsigned char *end;
    int i;

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        cleanup();
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(FILENAME, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        cleanup();
        return EXIT_FAILURE;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error re-queuing buffer: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    cleanup();
    printf("Image saved to %s\n", FILENAME);
    return EXIT_SUCCESS;
}

