#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27
#define PWM_RANGE 1000
#define PWM_FREQ 1000
#define SLEEP_SEC 0.5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0 ||
        gpioSetPWMrange(PWM_PIN_3, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQ) != 0 ||
        gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int v1 = rand() % PWM_RANGE;
        int v2 = rand() % PWM_RANGE;
        int v3 = rand() % PWM_RANGE;

        if (gpioPWM(PWM_PIN_1, v1) != 0 ||
            gpioPWM(PWM_PIN_2, v2) != 0 ||
            gpioPWM(PWM_PIN_3, v3) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle.\n");
            break;
        }

        printf("PWM 1: %4d  PWM 2: %4d  PWM 3: %4d\n", v1, v2, v3);
        fflush(stdout);

        time_sleep(SLEEP_SEC);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
