#define DHT22_PIN 4
#define DHT22_CHIP "gpiochip4"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int wait_for_line(struct gpiod_line *line, int val, int timeout_us) {
    unsigned int start = 0;
    while (running) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == val) return 0;
        if (start == 0) start = 1;
        else {
            if ((unsigned int)(clock() - start) * 1000 > timeout_us) return -1;
        }
        sleep_us(1);
    }
    return -1;
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    sleep_us(500);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    sleep_us(40);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_line(line, 0, 1000) < 0) return -2;
    if (wait_for_line(line, 1, 1000) < 0) return -2;
    if (wait_for_line(line, 0, 1000) < 0) return -2;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 1000) < 0) return -2;
        if (wait_for_line(line, 0, 1000) < 0) return -2;
        sleep_us(50);
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        data[i / 8] <<= 1;
        if (val) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    *hum = (float)raw_h / 10.0f;
    if (raw_t & 0x8000) *temp = -(float)(raw_t & 0x7FFF) / 10.0f;
    else *temp = (float)raw_t / 10.0f;

    if (*temp < -40.0f || *temp > 80.0f || *hum < 0.0f || *hum > 100.0f) return -4;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    float temp = 0.0f, hum = 0.0f;
    int rc = 1;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name(DHT22_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    int r = read_dht22(line, &temp, &hum);
    if (r == 0) {
        printf("Temperature: %.1f C, Humidity: %.1f %%\n", temp, hum);
        rc = 0;
    } else {
        fprintf(stderr, "DHT22 read failed (code %d)\n", r);
    }

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};
    int pins[4] = {GPIO_17, GPIO_23, GPIO_24, GPIO_25};
    int i;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (i = 0; i < 4; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for GPIO %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        for (i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO 17, 23, 24, 25 set HIGH\n");
        fflush(stdout);
        sleep(10);

        for (i = 0; i < 4; i++) {
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "gpiod_line_set_value failed for GPIO %d\n", pins[i]);
                goto cleanup;
            }
        }
        printf("GPIO 17, 23, 24, 25 set LOW\n");
        fflush(stdout);
        sleep(10);
    }

cleanup:
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define DEFAULT_MQTT_BROKER "localhost"
#define DEFAULT_MQTT_PORT 1883
#define DEFAULT_MQTT_TOPIC "sensor_data"
#define DEFAULT_MQTT_CLIENT_ID "mcp3008_reader"
#define DEFAULT_MCP3008_CHANNEL 0
#define DEFAULT_MCP3008_RANGE 1023
#define DEFAULT_PUBLISH_INTERVAL 1

static volatile sig_atomic_t running = 1;
static int mqtt_client_id = 0;
static MQTTClient mqtt_client = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    int handle = gpioRead(channel);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to read GPIO channel %d\n", channel);
        return -1;
    }

    return handle;
}

static int publish_sensor_data(const char *topic, int sensor_value) {
    char payload[32];
    snprintf(payload, sizeof(payload), "%d", sensor_value);

    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = payload;
    pubmsg.payloadlen = (int)strlen(payload);
    pubmsg.qos = 0;
    pubmsg.retained = 0;

    int rc = MQTTClient_publishMessage(mqtt_client, topic, &pubmsg);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to publish message to topic %s: %s\n", topic, MQTTClient_strerror(rc));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int mcp3008_channel = DEFAULT_MCP3008_CHANNEL;
    int mcp3008_range = DEFAULT_MCP3008_RANGE;
    int publish_interval = DEFAULT_PUBLISH_INTERVAL;
    char *mqtt_broker = DEFAULT_MQTT_BROKER;
    int mqtt_port = DEFAULT_MQTT_PORT;
    char *mqtt_topic = DEFAULT_MQTT_TOPIC;
    char *mqtt_client_id = DEFAULT_MQTT_CLIENT_ID;

    int opt;
    while ((opt = getopt(argc, argv, "b:p:t:c:r:i:")) != -1) {
        switch (opt) {
            case 'b': mqtt_broker = optarg; break;
            case 'p': mqtt_port = atoi(optarg); break;
            case 't': mqtt_topic = optarg; break;
            case 'c': mcp3008_channel = atoi(optarg); break;
            case 'r': mcp3008_range = atoi(optarg); break;
            case 'i': publish_interval = atoi(optarg); break;
            default:
                fprintf(stderr, "Usage: %s [-b broker] [-p port] [-t topic] [-c channel] [-r range] [-i interval]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(mcp3008_channel, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as input\n", mcp3008_channel);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_create(&mqtt_client, mqtt_broker, mqtt_client_id, MQTTCLIENT_PERSISTENCE_NONE, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&mqtt_client);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MCP3008 sensor reader started. Publishing to %s every %d seconds.\n", mqtt_topic, publish_interval);

    while (running) {
        int sensor_value = read_mcp3008(mcp3008_channel);
        if (sensor_value >= 0 && sensor_value <= mcp3008_range) {
            if (publish_sensor_data(mqtt_topic, sensor_value) != 0) {
                fprintf(stderr, "Warning: Failed to publish sensor data\n");
            }
        } else {
            fprintf(stderr, "Warning: Invalid sensor reading: %d\n", sensor_value);
        }
        sleep(publish_interval);
    }

    printf("\nShutting down...\n");
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
    gpioTerminate();
    printf("MCP3008 sensor reader stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FILENAME "image.jpg"

static int fd = -1;
static void *buffer = NULL;

int init_camera(void);
void close_camera(void);
int capture_image(const char *filename);
void cleanup(void);

int main(void) {
    if (init_camera() < 0) {
        fprintf(stderr, "Error: Could not initialize camera.\n");
        return EXIT_FAILURE;
    }

    if (capture_image(FILENAME) < 0) {
        fprintf(stderr, "Error: Could not capture image.\n");
        close_camera();
        return EXIT_FAILURE;
    }

    close_camera();
    return EXIT_SUCCESS;
}

int init_camera(void) {
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device.\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O.\n", DEVICE_NAME);
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        close(fd);
        fd = -1;
        return -1;
    }

    return 0;
}

void close_camera(void) {
    if (buffer != NULL && buffer != MAP_FAILED) {
        munmap(buffer, IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2);
        buffer = NULL;
    }
    if (fd >= 0) {
        close(fd);
        fd = -1;
    }
}

int capture_image(const char *filename) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    do {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "Error during select: %s\n", strerror(errno));
            ioctl(fd, VIDIOC_STREAMOFF, &type);
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "Error: Stream did not return data within timeout.\n");
            ioctl(fd, VIDIOC_STREAMOFF, &type);
            return -1;
        }
    } while (0);

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    fclose(fp);

    if (written != buf.bytesused) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        unlink(filename);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        unlink(filename);
        ioctl(fd, VIDIOC_STREAMOFF, &type);
        return -1;
    }

    ioctl(fd, VIDIOC_STREAMOFF, &type);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 5
#define PWM_PIN_3 6
#define PWM_PIN_4 7
#define PWM_PIN_5 8
#define PWM_PIN_6 9

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5, PWM_PIN_6};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM applied to GPIO 4, 5, 6, 7, 8, 9 (50%% duty cycle).\n");

    while (running) {
        gpioDelay(100000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }

    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    ret = gpiod_line_request_output(line17, "gpio17", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }

    ret = gpiod_line_request_output(line18, "gpio18", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 18");
        goto cleanup;
    }

    printf("Starting GPIO control. Press Ctrl+C to exit.\n");

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        printf("Cycle %d: GPIO 17 = HIGH, GPIO 18 = LOW\n", i + 1);
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value 17");
            break;
        }
        ret = gpiod_line_set_value(line18, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value 18");
            break;
        }
        sleep(1);

        printf("Cycle %d: GPIO 17 = LOW, GPIO 18 = HIGH\n", i + 1);
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value 17");
            break;
        }
        ret = gpiod_line_set_value(line18, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value 18");
            break;
        }
        sleep(1);
    }

    printf("\nExiting...\n");

cleanup:
    /* Release lines and close chip on all exit paths */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 17
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d (BCM) started. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (running) {
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE_OFFSET);
        sleep(POLL_INTERVAL_SEC);

        if (!running) break;

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE_OFFSET);
        sleep(POLL_INTERVAL_SEC);
    }

    /* Clean up: set line LOW and release resources */
    if (line) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define PCF8574_ADDR 0x3F
#define I2C_BUS "/dev/i2c-1"

static int i2c_fd = -1;

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static void signal_handler(int sig) {
    (void)sig;
    cleanup();
    exit(0);
}

static int i2c_write_byte(int fd, unsigned char value) {
    if (write(fd, &value, 1) != 1) {
        perror("i2c write failed");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        cleanup();
        return 1;
    }

    while (1) {
        int value = rand() % 100;
        if (i2c_write_byte(i2c_fd, (unsigned char)value) < 0) {
            cleanup();
            return 1;
        }
        usleep(500000);
    }

    cleanup();
    return 0;
}

