        goto streamoff;
    }

    size_t written = fwrite(buffer, 1, buf.bytesused, fp);
    if (written != buf.bytesused) {
        fprintf(stderr, "Short write: %zu of %u bytes\n", written, buf.bytesused);
        fclose(fp);
        goto streamoff;
    }

    if (fclose(fp) != 0) {
