#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define TIMEOUT_US  300000  /* 300 ms timeout for echo */

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        perror("gpiod_chip_get_line(trigger)");
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        perror("gpiod_chip_get_line(echo)");
        goto cleanup;
    }

    /* Request trigger as output, initial value LOW */
    if (gpiod_line_request_output(trig, "hcsr04-trigger", 0) < 0) {
        perror("gpiod_line_request_output(trigger)");
        goto cleanup;
    }

    /* Request echo as input */
    if (gpiod_line_request_input(echo, "hcsr04-echo") < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }

    /* Ensure trigger starts LOW */
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger, 0)");
        goto cleanup;
    }

    /* Allow sensor to settle */
    usleep(50000);

    /* Send 10 us trigger pulse */
    if (gpiod_line_set_value(trig, 1) < 0) {
        perror("gpiod_line_set_value(trigger, 1)");
        goto cleanup;
    }
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) {
        perror("gpiod_line_set_value(trigger, 0)");
        goto cleanup;
    }

    /* Wait for echo to go HIGH (start of pulse) */
    int waited = 0;
    while (running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            goto cleanup;
        }
        if (val == 1) {
            break;
        }
        usleep(10);
        if (++waited > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pin did not go HIGH (sensor absent or not responding)\n");
            goto cleanup;
        }
    }

    if (!running) {
        goto cleanup;
    }

    /* Measure echo pulse width */
    long long start = 0;
    long long end = 0;
    waited = 0;

    while (running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            goto cleanup;
        }
        if (val == 1) {
            start = (long long)clock() * 1000000LL / CLOCKS_PER_SEC;
            break;
        }
        usleep(10);
        if (++waited > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse start timeout\n");
            goto cleanup;
        }
    }

    if (!running) {
        goto cleanup;
    }

    waited = 0;
    while (running) {
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(echo)");
            goto cleanup;
        }
        if (val == 0) {
            end = (long long)clock() * 1000000LL / CLOCKS_PER_SEC;
            break;
        }
        usleep(10);
        if (++waited > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse end timeout\n");
            goto cleanup;
        }
    }

    if (!running) {
        goto cleanup;
    }

    long long elapsed = end - start;
    double distance = (elapsed / 2.0) * 0.0343; /* cm */

    printf("Distance: %.2f cm\n", distance);

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) {
        gpiod_line_release(trig);
    }
    if (echo) {
        gpiod_line_release(echo);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

