#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device absent or permissions).\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handlers.\n");
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_3, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_PIN_4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[4] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    for (int i = 0; i < 4; i++) {
        if (gpioSetPWMfrequency(pins[i], 1000) < 0) {
            fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < 4; i++) {
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Error: failed to set PWM duty cycle on GPIO %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("PWM applied to GPIO %d, %d, %d, %d (50%% duty).\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4);

    while (running) {
        sleep(1);
    }

    for (int i = 0; i < 4; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define PERIOD_SEC 1

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL, *line3 = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(GPIO_2)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line(GPIO_3)");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request both lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line2, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_2)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line3, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output(GPIO_3)");
        goto cleanup;
    }

    /* Main loop: toggle once per second, report, until interrupted */
    while (running) {
        ret = gpiod_line_set_value(line2, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_2)");
            break;
        }
        printf("GPIO 2 set HIGH\n");
        fflush(stdout);

        sleep(PERIOD_SEC);

        if (!running) break;

        ret = gpiod_line_set_value(line2, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_2)");
            break;
        }
        printf("GPIO 2 set LOW\n");
        fflush(stdout);

        sleep(PERIOD_SEC);

        if (!running) break;

        ret = gpiod_line_set_value(line3, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_3)");
            break;
        }
        printf("GPIO 3 set HIGH\n");
        fflush(stdout);

        sleep(PERIOD_SEC);

        if (!running) break;

        ret = gpiod_line_set_value(line3, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value(GPIO_3)");
            break;
        }
        printf("GPIO 3 set LOW\n");
        fflush(stdout);
    }

cleanup:
