#define GPIO_18 18
#define GPIO_27 27
#define CONSUMER "toggle_test"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        perror("gpiod_chip_get_line 18");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line 27");
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output 18");
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output 27");
        goto cleanup;
    }

    int val = 0;
    while (running) {
        if (gpiod_line_set_value(line18, val) < 0) {
            perror("gpiod_line_set_value 18");
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, val) < 0) {
            perror("gpiod_line_set_value 27");
            goto cleanup;
        }
        printf("GPIO 18: %d, GPIO 27: %d\n", val, val);
        fflush(stdout);
        val = !val;
        usleep(10000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line18) gpiod_line_release(line18);
    if (line27) gpiod_line_release(line27);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

