#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_8 8
#define GPIO_17 17

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line8 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line8 = gpiod_chip_get_line(chip, GPIO_8);
    if (!line8) {
        perror("gpiod_chip_get_line 8");
        goto cleanup;
    }
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line 17");
        goto cleanup;
    }

    /* Request lines as outputs, initial low */
    ret = gpiod_line_request_output(line8, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 8");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line17, "digital_output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output 17");
        goto cleanup;
    }

    /* Apply states and report */
    ret = gpiod_line_set_value(line8, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value 8");
        goto cleanup;
    }
    ret = gpiod_line_set_value(line17, 1);
    if (ret < 0) {
        perror("gpiod_line_set_value 17");
        goto cleanup;
    }
    printf("GPIO 8 and GPIO 17 set HIGH\n");

    /* Wait for signal or completion */
    while (running) {
        sleep(1);
    }

    /* Turn off and release */
    gpiod_line_set_value(line8, 0);
    gpiod_line_set_value(line17, 0);
    printf("GPIO 8 and GPIO 17 set LOW\n");

cleanup:
    /* Release lines and close chip */
    if (line8) gpiod_line_release(line8);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 18
#define CONSUMER "digital_output"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handler for clean shutdown */
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the line for GPIO 18 */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW */
    ret = gpiod_line_request_output(line, CONSUMER, 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d started. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int value = 0;
        ret = gpiod_line_get_value(line);
        if (ret < 0) {
            perror("gpiod_line_get_value");
            /* Attempt to set a safe default and continue */
            gpiod_line_set_value(line, 0);
            sleep(1);
            continue;
        }

        if (ret != 0 && ret != 1) {
            fprintf(stderr, "Invalid GPIO value read: %d\n", ret);
            /* Attempt to set a safe default and continue */
            gpiod_line_set_value(line, 0);
            sleep(1);
            continue;
        }

        value = ret;
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            /* Attempt to set a safe default and continue */
            gpiod_line_set_value(line, 0);
            sleep(1);
            continue;
        }

        printf("GPIO %d set to %d\n", GPIO_PIN, value);
        sleep(5);
    }

    /* Clean up: set line low and release resources */
    gpiod_line_set_value(line, 0);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices"
#define W1_SLAVE_DIR_FORMAT "%s/w1_slave"
#define MAX_PATH_LENGTH 256
#define MAX_RETRIES 3

static volatile sig_atomic_t g_interrupted = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_interrupted = 1;
}

static int read_temperature(const char *device_path, float *temperature) {
    char path[MAX_PATH_LENGTH];
    int ret = snprintf(path, sizeof(path), W1_SLAVE_DIR_FORMAT, device_path);
    if (ret < 0 || (size_t)ret >= sizeof(path)) {
        fprintf(stderr, "Error: path too long\n");
        return -1;
    }

    FILE *fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    char line1[256];
    char line2[256];

    if (fgets(line1, sizeof(line1), fp) == NULL) {
        fprintf(stderr, "Error reading first line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fgets(line2, sizeof(line2), fp) == NULL) {
        fprintf(stderr, "Error reading second line from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (strstr(line1, "YES") == NULL) {
        fprintf(stderr, "Error: sensor not present (line1: %s)\n", line1);
        return -1;
    }

    char *temp_str = strstr(line2, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: temperature data not found in %s\n", path);
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    *temperature = (float)temp_raw / 1000.0f;

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    char w1_devices_path[MAX_PATH_LENGTH];
    int ret = snprintf(w1_devices_path, sizeof(w1_devices_path), "%s/28-00000...", W1_DEVICES_DIR);
    if (ret < 0 || (size_t)ret >= sizeof(w1_devices_path)) {
        fprintf(stderr, "Error: device path too long\n");
        return 1;
    }

    if (access(w1_devices_path, F_OK) != 0) {
        fprintf(stderr, "Error: %s not found. Is the DS18B20 connected and w1-gpio loaded?\n", w1_devices_path);
        return 1;
    }

    float temperature;
    int success_count = 0;

    for (int i = 0; i < 3 && !g_interrupted; i++) {
        if (read_temperature(w1_devices_path, &temperature) == 0) {
            printf("Temperature: %.2f C\n", temperature);
            fflush(stdout);
            success_count++;
        } else {
            fprintf(stderr, "Error reading temperature from %s\n", w1_devices_path);
        }

        if (i < 2 && !g_interrupted) {
            sleep(5);
        }
    }

    if (g_interrupted) {
        fprintf(stderr, "\nInterrupted by signal. Exiting.\n");
    } else if (success_count == 0) {
        fprintf(stderr, "Error: No successful temperature readings. Exiting.\n");
    }

    return (success_count > 0) ? 0 : 1;
}

