#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN  18
#define ECHO_PIN     23
#define ECHO2_PIN    24
#define CONSUMER     "hcsr04"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *echo2 = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    echo2 = gpiod_chip_get_line(chip, ECHO2_PIN);
    if (!trig || !echo || !echo2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(trig)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo) < 0) {
        perror("gpiod_line_request_input(echo)");
        goto cleanup;
    }
    if (gpiod_line_request_input(echo2) < 0) {
        perror("gpiod_line_request_input(echo2)");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        long long t0 = 0, t1 = 0;
        int v;
        long long elapsed = 0;

        while (running) {
            v = gpiod_line_get_value(echo);
            if (v < 0) {
                perror("gpiod_line_get_value(echo)");
                break;
            }
            if (v == 1) {
                t0 = elapsed;
            } else if (v == 0) {
                t1 = elapsed;
                break;
            }
            usleep(1);
            elapsed++;
        }

        if (!running) break;

        long long duration = t1 - t0;
        if (duration > 0 && duration < 300000) {
            printf("Distance: %.2f cm\n", duration / 58.0);
        } else {
            printf("Distance: out of range or sensor error\n");
        }

        usleep(100000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (echo2) gpiod_line_release(echo2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

