#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 8
#define NUM_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value LOW */
    if (gpiod_line_request_output(line, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output on GPIO %d: LOW\n", GPIO_LINE_OFFSET);

    /* Perform the cycles */
    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set line %d HIGH: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d -> HIGH\n", i + 1, GPIO_LINE_OFFSET);
        usleep(100000); /* 100 ms */

        if (!running) break;

        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to set line %d LOW: %s\n", GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d -> LOW\n", i + 1, GPIO_LINE_OFFSET);
        usleep(100000); /* 100 ms */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip */
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program finished.\n");
    }
    return ret;
}

