#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define DHT22_CHIP "gpiochip4"
#define MAX_CYCLES 3

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_us(unsigned int us) {
    struct timespec ts = {
        .tv_sec = us / 1000000,
        .tv_nsec = (long)(us % 1000000) * 1000
    };
    nanosleep(&ts, NULL);
}

static int wait_for_line(struct gpiod_line *line, int val, unsigned int timeout_us) {
    unsigned int start = 0;
    while (1) {
        if (gpiod_line_get_value(line) == val) return 0;
        if (!running) return -1;
        if (timeout_us == 0) return -1;
        sleep_us(1);
        timeout_us--;
        start++;
        if (start > 100000) return -1;
    }
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    sleep_us(500);
    gpiod_line_set_value(line, 0);
    sleep_us(20000);
    gpiod_line_set_value(line, 1);
    sleep_us(30);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_line(line, 0, 100) < 0) return -1;
    if (wait_for_line(line, 1, 100) < 0) return -1;
    if (wait_for_line(line, 0, 100) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 100) < 0) return -1;
        if (wait_for_line(line, 0, 100) < 0) return -1;
        sleep_us(50);
        if (gpiod_line_get_value(line) == 1) data[i / 8] |= (1 << (7 - (i % 8)));
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -2;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = 1;

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
