#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 27
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN_1, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN_2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN_1, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN_2, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range for GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int val1 = 500;
    int val2 = 300;

    if (gpioPWM(PWM_PIN_1, val1) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(PWM_PIN_2, val2) != 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", PWM_PIN_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM on GPIO %d = %d, GPIO %d = %d\n", PWM_PIN_1, val1, PWM_PIN_2, val2);

    while (running) {
        sleep(1);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

