#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 23
#define PWM_PIN_5 24
#define PWM_PIN_6 25

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5, PWM_PIN_6};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialise PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
