    while (running) {
        for (int i = 0; i < 6 && running; ++i) {
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                break;
            }
            printf("PWM on GPIO %d = 128\n", pins[i]);
        }
        if (!running) break;
        usleep(50000);
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

