#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define DHT22_PIN_1 4
#define DHT22_PIN_2 17
#define NUM_CYCLES 3
#define SLEEP_SECONDS 60

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static void sleep_seconds(int seconds) {
    while (seconds > 0 && running) {
        seconds = sleep(seconds);
    }
}

static int wait_for_line(struct gpiod_line *line, int target, int timeout_ms) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == target) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L +
                          (now.tv_nsec - start.tv_nsec) / 1000000L;
        if (elapsed_ms >= timeout_ms) return -1;
    }
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 1) < 0) return -1;
    gpiod_line_set_value(line, 1);
    usleep(500000);
    gpiod_line_set_value(line, 0);
    usleep(20000);
    gpiod_line_set_value(line, 1);
    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_line(line, 0, 1000) < 0) return -2;
    if (wait_for_line(line, 1, 1000) < 0) return -2;
    if (wait_for_line(line, 0, 1000) < 0) return -2;

    for (i = 0; i < 40; i++) {
        if (wait_for_line(line, 1, 1000) < 0) return -2;
        if (wait_for_line(line, 0, 1000) < 0) return -2;
        if (i % 2 == 0) {
            data[i / 2] <<= 1;
        } else {
            data[i / 2] |= (gpiod_line_get_value(line) & 1);
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -3;

    *hum = (float)((data[0] << 8) | data[1]) / 10.0f;
    *temp = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) *temp = -*temp;
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL, *line2 = NULL;
    int ret = 1;

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    line1 = gpiod_chip_get_line(chip, DHT22_PIN_1);
    line2 = gpiod_chip_get_line(chip, DHT22_PIN_2);
    if (!line1 || !line2) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        float temp = 0.0f, hum = 0.0f;
        int rc = read_dht22(line1, &temp, &hum);
        if (rc == 0) {
            printf("Cycle %d: Temp = %.1f C, Hum = %.1f %%\n", cycle + 1, temp, hum);
        } else {
            fprintf(stderr, "Cycle %d: DHT22 read failed (rc=%d)\n", cycle + 1, rc);
        }
        sleep_seconds(SLEEP_SECONDS);
    }

    ret = 0;

cleanup:
    if (line1) gpiod_line_release(line1);
    if (line2) gpiod_line_release(line2);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

