#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS 8
#define SPI_MODE 0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }

    return 0;
}

static int spi_read(int fd, uint8_t *data) {
    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = (unsigned long)data,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void process_data(const uint8_t *data, float *temperature, float *internal) {
    int16_t raw_temp = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_int = (int16_t)((data[2] << 8) | data[3]);

    *temperature = (float)raw_temp * 0.0625f;
    *internal = (float)raw_int * 0.0625f;
}

int main(void) {
    int fd = -1;
    uint8_t data[4];
    float temperature, internal;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init(&fd) < 0) {
        return 1;
    }

    if (!g_running) {
        fprintf(stderr, "Interrupted before reading.\n");
        close(fd);
        return 1;
    }

    if (spi_read(fd, data) < 0) {
        fprintf(stderr, "Error reading SPI data.\n");
        close(fd);
        return 1;
    }

    process_data(data, &temperature, &internal);

    printf("Temperature: %.2f C\n", temperature);
    printf("Internal: %.2f C\n", internal);

    close(fd);
    return 0;
}

