#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIG_PIN 4
#define ECHO_PIN 17
#define TRIG2_PIN 18
#define ECHO2_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIG_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *trig2 = gpiod_chip_get_line(chip, TRIG2_PIN);
    struct gpiod_line *echo2 = gpiod_chip_get_line(chip, ECHO2_PIN);

    if (!trig || !echo || !trig2 || !echo2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0 ||
        gpiod_line_request_output(trig2, "hc-sr04-trig2", 0) < 0 ||
        gpiod_line_request_input(echo2, "hc-sr04-echo2") < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa = {0};
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_line_release(trig2);
        gpiod_line_release(echo2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 sensor interface started. Press Ctrl+C to exit.\n");

    while (running) {
        /* Sensor 1 */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig)");
            break;
        }

        /* Wait for echo rising edge (timeout 30 ms) */
        int timeout = 30000;
        int val;
        while ((val = gpiod_line_get_value(echo)) == 0 && running) {
            usleep(1);
            if (--timeout <= 0) {
                printf("Sensor 1: No echo received (timeout)\n");
                break;
            }
        }
        if (val == 1) {
            /* Measure echo pulse width */
            timeout = 30000;
            while (running) {
                val = gpiod_line_get_value(echo);
                if (val == 0) break;
                usleep(1);
                if (--timeout <= 0) {
                    printf("Sensor 1: Echo stuck high (timeout)\n");
                    break;
                }
            }
            if (val == 0) {
                long long start = 0, end = 0;
                int count = 0;
                while (val == 0 && running) {
                    usleep(1);
                    val = gpiod_line_get_value(echo);
                    if (val == 1) start = (long long)clock() * 1000 / CLOCKS_PER_SEC;
                    else if (val == 0) {
                        end = (long long)clock() * 1000 / CLOCKS_PER_SEC;
                        count++;
                    }
                }
                if (count > 0 && running) {
                    long long duration = end - start;
                    float distance = (duration * 0.0343f) / 2.0f;
                    printf("Sensor 1: Distance = %.2f cm\n", distance);
                }
            }
        }

        /* Sensor 2 */
        if (gpiod_line_set_value(trig2, 1) < 0) {
            perror("gpiod_line_set_value(trig2)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig2, 0) < 0) {
            perror("gpiod_line_set_value(trig2)");
            break;
        }

        /* Wait for echo rising edge (timeout 30 ms) */
        timeout = 30000;
        val = gpiod_line_get_value(echo2);
        while (val == 0 && running) {
            usleep(1);
            if (--timeout <= 0) {
                printf("Sensor 2: No echo received (timeout)\n");
                break;
            }
            val = gpiod_line_get_value(echo2);
        }
        if (val == 1) {
            /* Measure echo pulse width */
            timeout = 30000;
            while (running) {
                val = gpiod_line_get_value(echo2);
                if (val == 0) break;
                usleep(1);
                if (--timeout <= 0) {
                    printf("Sensor 2: Echo stuck high (timeout)\n");
                    break;
                }
            }
            if (val == 0) {
                long long start = 0, end = 0;
                int count = 0;
                while (val == 0 && running) {
                    usleep(1);
                    val = gpiod_line_get_value(echo2);
                    if (val == 1) start = (long long)clock() * 1000 / CLOCKS_PER_SEC;
                    else if (val == 0) {
                        end = (long long)clock() * 1000 / CLOCKS_PER_SEC;
                        count++;
                    }
                }
                if (count > 0 && running) {
                    long long duration = end - start;
                    float distance = (duration * 0.0343f) / 2.0f;
                    printf("Sensor 2: Distance = %.2f cm\n", distance);
                }
            }
        }

        usleep(50000);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(trig2);
    gpiod_line_release(echo2);
    gpiod_chip_close(chip);
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

