#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_ADDR 0x03
#define I2C_DEV "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t init[3] = {0x72, 0x01, 0x00};
    if (i2c_write(fd, init, sizeof(init)) < 0) return -1;
    usleep(2000);
    uint8_t chip_id;
    if (i2c_read(fd, &chip_id, 1) < 0) return -1;
    if (chip_id != 0x58) {
        fprintf(stderr, "BMP280 not detected (chip_id=0x%02x)\n", chip_id);
        return -1;
    }
    uint8_t config[3] = {0x75, 0x02, 0x00};
    if (i2c_write(fd, config, sizeof(config)) < 0) return -1;
    return 0;
}

static int bmp280_read(int fd, float *temp, float *press) {
    uint8_t data[6];
    if (i2c_read(fd, data, sizeof(data)) < 0) return -1;
    uint32_t raw_press = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | (data[2] >> 4);
    uint32_t raw_temp = ((uint32_t)data[3] << 12) | ((uint32_t)data[4] << 4) | (data[5] >> 4);
    *press = (float)raw_press / 100.0f;
    *temp = (float)raw_temp / 100.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEV, strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave 0x%02x: %s\n", BMP280_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bmp280_init(fd) < 0) {
        fprintf(stderr, "BMP280 init failed\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        float temp, press;
        if (bmp280_read(fd, &temp, &press) == 0) {
            printf("Reading %d: Temperature = %.2f C, Pressure = %.2f hPa\n", i + 1, temp, press);
        } else {
            fprintf(stderr, "Read %d failed\n", i + 1);
        }
        if (i < 2) usleep(100000);
    }

    close(fd);
    return 0;
}

