    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", pins[i]);
            goto cleanup;
        }
    }

    for (int i = 0; i < 4; i++) {
        ret = gpiod_line_request_output(lines[i], "digital_output", values[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d as output\n", pins[i]);
            goto cleanup;
        }
    }

    printf("Applying states: GPIO17=1, GPIO22=0, GPIO23=1, GPIO24=0\n");

    for (int i = 0; i < 4; i++) {
        ret = gpiod_line_set_value(lines[i], values[i]);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line %d\n", pins[i]);
            goto cleanup;
        }
    }

    while (running) {
        sleep(1);
    }

    printf("\nExiting cleanly.\n");

cleanup:
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

