#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_4 4
#define GPIO_17 17
#define NUM_CYCLES 5

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret;

    /* Install signal handler for clean exit */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get lines */
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("gpiod_chip_get_line (GPIO 4)");
        goto cleanup;
    }
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line (GPIO 17)");
        goto cleanup;
    }

    /* Request lines as outputs, initial value LOW */
    ret = gpiod_line_request_output(line4, "gpio4", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 4)");
        goto cleanup;
    }
    ret = gpiod_line_request_output(line17, "gpio17", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output (GPIO 17)");
        goto cleanup;
    }

    printf("Starting 5 cycles of GPIO 4 and GPIO 17 toggling...\n");

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
            break;
        }
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            break;
        }
        printf("Cycle %d: GPIO 4 = HIGH, GPIO 17 = HIGH\n", i + 1);

        usleep(100000); /* 100 ms */

        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 4)");
            break;
        }
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value (GPIO 17)");
            break;
        }
        printf("Cycle %d: GPIO 4 = LOW, GPIO 17 = LOW\n", i + 1);

        usleep(100000); /* 100 ms */
    }

    printf("Exiting cleanly.\n");

cleanup:
    /* Release lines (safe to call even if request failed) */
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

