#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TRIGGER2_PIN 27

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    struct gpiod_line *trig2 = gpiod_chip_get_line(chip, TRIGGER2_PIN);
    if (!trig || !echo || !trig2) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        perror("gpiod_line_request_output trig");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request_input echo");
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(trig2, "hc-sr04-trig2", 0) < 0) {
        perror("gpiod_line_request_output trig2");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpiod_line_release(trig);
        gpiod_line_release(echo);
        gpiod_line_release(trig2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    gpiod_line_set_value(trig, 0);
    usleep(1000);
    gpiod_line_set_value(trig, 1);
    usleep(10);
    gpiod_line_set_value(trig, 0);

    while (running) {
        gpiod_line_set_value(trig2, 0);
        usleep(1000);
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value");
            break;
        }
        if (val == 1) {
            gpiod_line_set_value(trig2, 1);
            while (running) {
                val = gpiod_line_get_value(echo);
                if (val < 0) {
                    perror("gpiod_line_get_value");
                    break;
                }
                if (val == 0) break;
                usleep(1);
            }
            gpiod_line_set_value(trig2, 0);
            if (val == 0) {
                printf("Echo detected\n");
            }
        }
        usleep(10000);
    }

    gpiod_line_set_value(trig, 0);
    gpiod_line_set_value(trig2, 0);
    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_line_release(trig2);
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

