        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("PWM applied to GPIO %d, %d, %d (duty 128/255)\n",
           PWM_PIN_1, PWM_PIN_2, PWM_PIN_3);

    while (running) {
        gpioDelay(100000);
    }

    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();
    printf("PWM stopped and pigpio terminated.\n");
    return EXIT_SUCCESS;
}

