#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_ID 0x12
#define TCS34725_CDATAL 0x14
#define TCS34725_CDATAH 0x15
#define TCS34725_RDATAL 0x16
#define TCS34725_RDATAH 0x17
#define TCS34725_GDATAL 0x18
#define TCS34725_GDATAH 0x19
#define TCS34725_BDATAL 0x1A
#define TCS34725_BDATAH 0x1B

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { (uint8_t)(reg | 0x80), val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    uint8_t cmd = (uint8_t)(reg | 0x80);
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg_low, uint16_t *val) {
    uint8_t low, high;
    if (i2c_read_byte(fd, reg_low, &low) < 0) return -1;
    if (i2c_read_byte(fd, reg_low + 1, &high) < 0) return -1;
    *val = (uint16_t)((high << 8) | low);
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0) return -1;
    if (id != 0x44) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x44)\n", id);
        return -1;
    }
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ATIME, 0xFF) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        i2c_write_byte(i2c_fd, TCS34725_ENABLE, 0x00);
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        cleanup();
        return 1;
    }

    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        cleanup();
        return 1;
    }

    while (running) {
        uint16_t clear, red, green, blue;
        if (i2c_read_word(i2c_fd, TCS34725_CDATAL, &clear) < 0 ||
            i2c_read_word(i2c_fd, TCS34725_RDATAL, &red) < 0 ||
            i2c_read_word(i2c_fd, TCS34725_GDATAL, &green) < 0 ||
            i2c_read_word(i2c_fd, TCS34725_BDATAL, &blue) < 0) {
            fprintf(stderr, "Failed to read color data.\n");
            break;
        }
        printf("Clear: %u, Red: %u, Green: %u, Blue: %u\n", clear, red, green, blue);
        usleep(500000);
    }

    cleanup();
    return 0;
}

